-- Super Admin distribution platform catalog + property connection control
create table if not exists public.anaira_distribution_platforms (id uuid primary key default gen_random_uuid(), provider_code text not null unique, provider_name text not null, category text not null, description text, capabilities jsonb not null default '[]'::jsonb, integration_type text not null default 'rest_api', active boolean not null default true, config_schema jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.anaira_distribution_connections (id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants(id) on delete cascade, platform_id uuid not null references public.anaira_distribution_platforms(id) on delete cascade, status text not null default 'not_configured', base_url text, auth_type text not null default 'api_key', credentials_ref text, config jsonb not null default '{}'::jsonb, auto_sync boolean not null default false, inventory_sync boolean not null default true, rate_sync boolean not null default true, reservation_sync boolean not null default true, webhook_enabled boolean not null default false, last_sync_at timestamptz, last_error text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(restaurant_id,platform_id));
alter table public.ota_channels add column if not exists platform_id uuid references public.anaira_distribution_platforms(id) on delete set null;
